    ellipse(ctx, cx - w * 0.2, y + h * 0.32, w * 0.14, h * 0.12, 'rgba(255,255,255,0.3)');
    for (let i = 0; i < 7; i += 1) {
      const sx = cx + Math.cos(i * 2.3) * w * 0.3;
      const sy = y + h * (0.28 + 0.22 * Math.abs(Math.sin(i * 1.7)));
      ellipse(ctx, sx, sy, w * 0.025, w * 0.014, '#fff3d6');
