  ctx.save();
  ctx.translate(cx, base);
  ctx.scale(1 + 0.08 * s, 1 - 0.12 * s);
  ctx.translate(-cx, -base);
  draw();
  ctx.restore();
}

function drawBin(ctx, station) {
